 function personalList(){const rows=[...states].filter(([id])=>saved.has(String(id))).map(([id,s])=>({f:findFilm(id),s})).filter(x=>x.f);el('personal-movies').innerHTML=rows.length?rows.map(({f,s})=>`<li><strong>${esc(f.title)}</strong><span>${s==='watched'?'Visto':'Da vedere'}</span><button type="button" data-personal-seen="${esc(f.id)}">${s==='watched'?'Segna da vedere':'Segna visto'}</button><button type="button" data-remove-movie="${esc(f.id)}">Rimuovi</button></li>`).join(''):'<p>La tua lista è vuota. Aggiungi un film dal catalogo.</p>'}
