 async function setMovie(id,nextStatus){if(!user){open();message('Accedi per salvare la tua lista su tutti i dispositivi.');return false}if(!ready)throw Error('Attendi il caricamento del tuo account.');const key=String(id),mid=movieMap.get(key);if(!mid)throw Error('Film non ancora disponibile nella lista personale.');const uid=user.id;await checked(await db.from('user_movies').upsert({user_id:uid,movie_id:mid,status:nextStatus,is_saved:saved.has(key)},{onConflict:'user_id,movie_id'}));if(user?.id!==uid)return false;states.set(key,nextStatus);const f=findFilm(id);if(f){nextStatus==='watched'?seen.add(f.id):seen.delete(f.id)}paint();saveNote.textContent='Film sincronizzati con il tuo account.';return true}
 async function toggleSaved(id,remove=false){if(!user){open();message('Accedi per salvare la tua lista.');return}if(!ready)throw Error('Attendi il caricamento del tuo account.');const key=String(id),mid=movieMap.get(key),uid=user.id;if(!mid)throw Error('Film non ancora disponibile nella lista personale.');const active=!remove&&!saved.has(key);await checked(await db.from('user_movies').upsert({user_id:uid,movie_id:mid,status:states.get(key)||'watchlist',is_saved:active},{onConflict:'user_id,movie_id'}));if(user?.id!==uid)return;active?saved.add(key):saved.delete(key);if(!states.has(key))states.set(key,'watchlist');paint()}
 function open(){el('account-dialog').showModal();if(user&&!ready)loadUser(user)}
 function authMode(m){mode=m;el('auth-title').textContent=m==='signup'?'Crea il tuo account':m==='reset'?'Recupera la password':'Accedi a Horrify';el('auth-password-wrap').hidden=m==='reset';el('auth-password').required=m!=='reset';el('auth-password').autocomplete=m==='signup'?'new-password':'current-password';el('auth-submit').textContent=m==='signup'?'Registrati':m==='reset'?'Invia email di recupero':'Accedi';message('')}
 el('account-open').onclick=open;el('account-close').onclick=()=>el('account-dialog').close();el('account-dialog').addEventListener('click',e=>{if(e.target===el('account-dialog'))el('account-dialog').close()});document.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>authMode(b.dataset.authMode));
 el('auth-form').onsubmit=async e=>{e.preventDefault();const button=el('auth-submit');button.disabled=true;message('');try{const email=el('auth-email').value.trim(),password=el('auth-password').value;if(mode==='signup'){const data=await checked(await db.auth.signUp({email,password,options:{emailRedirectTo:location.origin+'/'}}));message(data.session?'Ottimo! Registrazione avvenuta con successo!':'Ottimo! Registrazione avviata con successo! Controlla la tua email e clicca sul link per confermare il tuo indirizzo. Poi torna qui per accedere.',false,true);if(data.session)await loadUser(data.user)}else if(mode==='reset'){await checked(await db.auth.resetPasswordForEmail(email,{redirectTo:location.origin+'/'}));message('Se l’indirizzo è registrato, riceverai un’email. Apri il link per scegliere una nuova password.');el('recovery-link-form').hidden=false}else{const data=await checked(await db.auth.signInWithPassword({email,password}));await loadUser(data.user);message('Accesso effettuato.')}}catch(err){fail(err)}finally{button.disabled=false}};
 el('recovery-link-form').onsubmit=async e=>{e.preventDefault();try{const u=new URL(el('recovery-link').value);if(u.origin!=='https://tvhdxnxnlllmnnbszaqd.supabase.co'||u.pathname!=='/auth/v1/verify'||u.searchParams.get('type')!=='recovery')throw Error('Incolla il link di recupero ricevuto da Horrify.');await checked(await db.auth.verifyOtp({token_hash:u.searchParams.get('token'),type:'recovery'}));el('recovery-link').value='';el('password-form').hidden=false;message('Scegli una nuova password.')}catch(err){fail(err)}};
