 el('profile-form').onsubmit=async e=>{e.preventDefault();try{await checked(await db.from('profiles').update({display_name:el('profile-name').value.trim()||null,username:el('profile-username').value.trim()||null,is_public:el('profile-public').checked}).eq('id',user.id));message('Profilo salvato.')}catch(err){fail(err)}};
 el('services-list').onchange=async e=>{const input=e.target;if(!input.matches('[data-service]'))return;input.disabled=true;const id=Number(input.dataset.service);try{const uid=user.id;if(input.checked)await checked(await db.from('user_streaming_services').insert({user_id:uid,service_id:id}));else await checked(await db.from('user_streaming_services').delete().eq('user_id',uid).eq('service_id',id));input.checked?selectedServices.add(id):selectedServices.delete(id);message('Servizi aggiornati.')}catch(err){input.checked=!input.checked;fail(err)}finally{input.disabled=false}};
