 return {updateCatalog(rows){movieMap=new Map(rows.map(m=>[String(HorrifyCatalog.idFor(m)),m.id]));paint()},get user(){return user},get savedOnly(){return savedOnly},matches,setMovie,rememberGuest(){guestSeen.clear();seen.forEach(id=>guestSeen.add(id))}};
